export function findOrder(n: number, prerequisites: number[][]): number[] {
const adj:number[][]=Array.from({length:n},()=>[]),degree:number[]=Array(n).fill(0);for(const [c,p] of prerequisites){adj[p].push(c);degree[c]++;}const ready:number[]=[];for(let i=0;i<n;i++)if(!degree[i])ready.push(i);const out:number[]=[];while(ready.length){ready.sort((a,b)=>a-b);const x=ready.shift()!;out.push(x);for(const y of adj[x])if(--degree[y]===0)ready.push(y);}return out.length===n?out:[];
}
